local root = Instance.new(\"Part\")\r\n        root.Name = \"HumanoidRootPart\"\r\n        root.Size = Vector3.new(2, 2, 1)\r\n        root.Transparency = 1\r\n        root.CanCollide = false\r\n        root.Anchored = true\r\n        root.CFrame = currentCFrame -- Use original CFrame\r\n        root.Parent = model\r\n        ANTILOCK_SETTINGS.VisualParts[\"HumanoidRootPart\"] = root\r\n\r\n        -- Create humanoid\r\n        local humanoid = Instance.new(\"Humanoid\")\r\n        humanoid.Name = \"Humanoid\"\r\n        humanoid.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None\r\n        humanoid.Parent = model\r\n        ANTILOCK_SETTINGS.VisualHumanoid = humanoid\r\n\r\n        model.Parent = workspace\r\n        ANTILOCK_SETTINGS.VisualModel = model\r\n\r\n        -- Update all part positions relative to the root\r\n        updateVisualCharacter()\r\n\r\n        -- Switch camera to visual character\r\n        workspace.CurrentCamera.CameraSubject = humanoid\r\n    end\r\n\r\n    local function removeVisualCharacter()\r\n        if ANTILOCK_SETTINGS.VisualModel then\r\n            -- Store the visual character\'s position before removing it\r\n            local visualRoot = ANTILOCK_SETTINGS.VisualParts[\"HumanoidRootPart\"]\r\n            if visualRoot then\r\n                -- Move real character to visual character\'s position\r\n                local character = player.Character\r\n                if character then\r\n                    local rootPart = character:FindFirstChild(\"HumanoidRootPart\")\r\n                    if rootPart then\r\n                        rootPart.CFrame = visualRoot.CFrame\r\n                        rootPart.Velocity = Vector3.new(0, 0, 0)\r\n                        rootPart.AssemblyLinearVelocity = Vector3.new(0, 0, 0)\r\n                    end\r\n                end\r\n            end\r\n\r\n            -- Switch camera back to real character\r\n            local character = player.Character\r\n            if character then\r\n                local humanoid = character:FindFirstChild(\"Humanoid\")\r\n                if humanoid then\r\n                    workspace.CurrentCamera.CameraSubject = humanoid\r\n                end\r\n            end\r\n\r\n            -- Clean up visual character\r\n            ANTILOCK_SETTINGS.VisualModel:Destroy()\r\n            ANTILOCK_SETTINGS.VisualModel = nil\r\n            ANTILOCK_SETTINGS.VisualParts = {}\r\n            ANTILOCK_SETTINGS.VisualHumanoid = nil\r\n        end\r\n    end\r\n\r\n    -- Update antilock orbit\r\n    local function updateAntilock(deltaTime)\r\n        if not ANTILOCK_SETTINGS.Enabled then return end\r\n\r\n        local character = player.Character\r\n        if not character then return end\r\n\r\n        local rootPart = character:FindFirstChild(\"HumanoidRootPart\")\r\n        local visualRoot = ANTILOCK_SETTINGS.VisualParts[\"HumanoidRootPart\"]\r\n        if not rootPart or not visualRoot then return end\r\n\r\n        if ANTILOCK_SETTINGS.VisualHumanoid and workspace.CurrentCamera.CameraSubject ~= ANTILOCK_SETTINGS.VisualHumanoid then\r\n            workspace.CurrentCamera.CameraSubject = ANTILOCK_SETTINGS.VisualHumanoid\r\n        end\r\n\r\n        -- Update random rotations\r\n        local randomX = math.random(-100, 100) * deltaTime\r\n        local randomY = math.random(-100, 100) * deltaTime\r\n        local randomZ = math.random(-100, 100) * deltaTime\r\n\r\n        -- Calculate a random direction vector for this frame\r\n        local theta = math.rad(math.random(0, 360))\r\n        local phi = math.rad(math.random(0, 360))\r\n        \r\n        -- Convert spherical coordinates to Cartesian\r\n        local dirX = math.sin(phi) * math.cos(theta)\r\n        local dirY = math.sin(phi) * math.sin(theta)\r\n        local dirZ = math.cos(phi)\r\n        \r\n        -- Create direction vector and normalize it\r\n        local direction = Vector3.new(dirX, dirY, dirZ).Unit\r\n        \r\n        -- Calculate target position\r\n        local targetPosition = visualRoot.Position + (direction * ANTILOCK_SETTINGS.Radius)\r\n        \r\n        -- Update real character position\r\n        rootPart.CFrame = CFrame.new(targetPosition) * CFrame.fromEulerAnglesXYZ(\r\n            math.rad(randomX), \r\n            math.rad(randomY), \r\n            math.rad(randomZ)\r\n        )\r\n        \r\n        -- Zero out velocity to prevent drift\r\n        rootPart.Velocity = Vector3.new(0, 0, 0)\r\n        rootPart.AssemblyLinearVelocity = Vector3.new(0, 0, 0)\r\n        \r\n        -- Update visual character\r\n        updateVisualCharacter()\r\n    end\r\n\r\n    local function handleVerticalMovement()\r\n        if not ANTILOCK_SETTINGS.Enabled or not ANTILOCK_SETTINGS.VisualModel then return end\r\n        \r\n        local character = player.Character\r\n        if not character then return end\r\n        \r\n        local visualRoot = ANTILOCK_SETTINGS.VisualParts[\"HumanoidRootPart\"]\r\n        if not visualRoot then return end\r\n        \r\n        -- Handle jumping/falling\r\n        if UserInputService:IsKeyDown(Enum.KeyCode.Space) then\r\n            visualRoot.CFrame = visualRoot.CFrame + Vector3.new(0, 1, 0)\r\n        elseif UserInputService:IsKeyDown(Enum.KeyCode.LeftControl) then\r\n            visualRoot.CFrame = visualRoot.CFrame + Vector3.new(0, -1, 0)\r\n        end\r\n    end\r\n\r\n    local function getPing()\r\n        local stats = game:GetService(\"Stats\")\r\n        local ping = math.floor(stats.Network.ServerStatsItem[\"Data Ping\"]:GetValue())\r\n        return ping\r\n    end\r\n    local function getAutoPrediction()\r\n        local ping = getPing()\r\n        \r\n        -- Define ping ranges and corresponding predictions\r\n        if ping <= 20 then\r\n            return AUTO_PREDICTION_SETTINGS.PingRanges.ping20_30\r\n        elseif ping <= 30 then\r\n            return AUTO_PREDICTION_SETTINGS.PingRanges.ping20_30\r\n        elseif ping <= 40 then\r\n            return AUTO_PREDICTION_SETTINGS.PingRanges.ping30_40\r\n        elseif ping <= 50 then\r\n            return AUTO_PREDICTION_SETTINGS.PingRanges.ping40_50\r\n        elseif ping <= 60 then\r\n            return AUTO_PREDICTION_SETTINGS.PingRanges.ping50_60\r\n        elseif ping <= 70 then\r\n            return AUTO_PREDICTION_SETTINGS.PingRanges.ping60_70\r\n        elseif ping <= 80 then\r\n            return AUTO_PREDICTION_SETTINGS.PingRanges.ping70_80\r\n        elseif ping <= 90 then\r\n            return AUTO_PREDICTION_SETTINGS.PingRanges.ping80_90\r\n        elseif ping <= 100 then\r\n            return AUTO_PREDICTION_SETTINGS.PingRanges.ping90_100\r\n        elseif ping <= 110 then\r\n            return AUTO_PREDICTION_SETTINGS.PingRanges.ping100_110\r\n        elseif ping <= 120 then\r\n            return AUTO_PREDICTION_SETTINGS.PingRanges.ping110_120\r\n        elseif ping <= 130 then\r\n            return AUTO_PREDICTION_SETTINGS.PingRanges.ping120_130\r\n        elseif ping <= 140 then\r\n            return AUTO_PREDICTION_SETTINGS.PingRanges.ping130_140\r\n        elseif ping <= 150 then\r\n            return AUTO_PREDICTION_SETTINGS.PingRanges.ping140_150\r\n        elseif ping <= 160 then\r\n            return AUTO_PREDICTION_SETTINGS.PingRanges.ping150_160\r\n        elseif ping <= 170 then\r\n            return AUTO_PREDICTION_SETTINGS.PingRanges.ping160_170\r\n        elseif ping <= 180 then\r\n            return AUTO_PREDICTION_SETTINGS.PingRanges.ping170_180\r\n        elseif ping <= 190 then\r\n            return AUTO_PREDICTION_SETTINGS.PingRanges.ping180_190\r\n        else\r\n            return AUTO_PREDICTION_SETTINGS.PingRanges.ping190_200\r\n        end\r\n    end\r\n\r\n    local function isOnSameTeam(player1, player2)\r\n        if not player1 or not player2 then return false end\r\n        \r\n        if player1.Team and player2.Team then\r\n            return player1.Team == player2.Team\r\n        end\r\n        \r\n        return false\r\n    end\r\n\r\n    local function updateNoclip()\r\n        if not NOCLIP_SETTINGS.Enabled then return end\r\n        \r\n        local character = player.Character\r\n        if not character then return end\r\n        \r\n        for _, child in pairs(character:GetDescendants()) do\r\n            if child:IsA(\"BasePart\") then\r\n                child.CanCollide = false\r\n            end\r\n        end\r\n    end\r\n\r\n    local function updateSpin(deltaTime)\r\n        if not spinEnabled or not player.Character then return end\r\n        \r\n        local rootPart = player.Character:FindFirstChild(\"HumanoidRootPart\")\r\n        if not rootPart then return end\r\n        \r\n        spinAngle = spinAngle + spinSpeed * deltaTime\r\n        local spinRotation = CFrame.Angles(0, spinAngle, 0)\r\n        local pos = rootPart.Position\r\n        rootPart.CFrame = CFrame.new(pos) * spinRotation\r\n    end\r\n\r\n    local function sendMessage(message)\r\n        if game:GetService(\"TextChatService\").ChatVersion == Enum.ChatVersion.TextChatService then\r\n            local textChannel = game:GetService(\"TextChatService\").TextChannels.RBXGeneral\r\n            textChannel:SendAsync(message)\r\n        else\r\n            game:GetService(\"ReplicatedStorage\"):WaitForChild(\"DefaultChatSystemChatEvents\")\r\n                :WaitForChild(\"SayMessageRequest\"):FireServer(message, \"All\")\r\n        end\r\n    end\r\n\r\n    -- Speech coroutine handling\r\n    local speechCoroutine = nil\r\n\r\n    local function startSpeech()\r\n        if speechCoroutine then\r\n            coroutine.close(speechCoroutine)\r\n        end\r\n        \r\n        speechCoroutine = coroutine.create(function()\r\n            while SPEECH_SETTINGS.Enabled do\r\n                for _, sentence in ipairs(sentences) do\r\n                    if not SPEECH_SETTINGS.Enabled then break end\r\n                    sendMessage(sentence)\r\n                    task.wait(SPEECH_SETTINGS.Delay)\r\n                end\r\n                task.wait(SPEECH_SETTINGS.LoopDelay)\r\n            end\r\n        end)\r\n        \r\n        coroutine.resume(speechCoroutine)\r\n    end\r\n\r\n    local function updateSpeed(deltaTime)\r\n        if not SPEED_SETTINGS.Enabled or not speedEnabled then return end\r\n        \r\n        local character = player.Character\r\n        if not character then return end\r\n        \r\n        local humanoid = character:FindFirstChild(\"Humanoid\")\r\n        local rootPart = character:FindFirstChild(\"HumanoidRootPart\")\r\n        if not humanoid or not rootPart then return end\r\n        \r\n        -- Only apply speed if the character is moving\r\n        if humanoid.MoveDirection.Magnitude > 0 then\r\n            -- Get movement direction\r\n            local moveDirection = humanoid.MoveDirection.Unit\r\n            \r\n            -- Set the character\'s speed\r\n            rootPart.CFrame = rootPart.CFrame + (moveDirection * SPEED_SETTINGS.Speed * deltaTime)\r\n        end\r\n    end\r\n\r\n    local function updateMovementVectors()\r\n        local cameraCFrame = camera.CFrame\r\n        local horizontalRotation = CFrame.new(Vector3.new(), Vector3.new(\r\n            cameraCFrame.LookVector.X,\r\n            0,\r\n            cameraCFrame.LookVector.Z\r\n        ).Unit)\r\n        horizontalLookVector = horizontalRotation.LookVector\r\n        horizontalRightVector = horizontalRotation.RightVector\r\n    end\r\n\r\n    local function calculateMovementDirection()\r\n        if UserInputService:GetFocusedTextBox() then\r\n            return Vector3.new(0, 0, 0)\r\n        end\r\n\r\n        moveDirection = Vector3.new(0, 0, 0)\r\n        if UserInputService:IsKeyDown(FLIGHT_SETTINGS.Controls.FORWARD) then\r\n            moveDirection = moveDirection + horizontalLookVector\r\n        end\r\n        if UserInputService:IsKeyDown(FLIGHT_SETTINGS.Controls.BACKWARD) then\r\n            moveDirection = moveDirection - horizontalLookVector\r\n        end\r\n        if UserInputService:IsKeyDown(FLIGHT_SETTINGS.Controls.RIGHT) then\r\n            moveDirection = moveDirection + horizontalRightVector\r\n        end\r\n        if UserInputService:IsKeyDown(FLIGHT_SETTINGS.Controls.LEFT) then\r\n            moveDirection = moveDirection - horizontalRightVector\r\n        end\r\n        \r\n        return moveDirection.Magnitude > 0 and moveDirection.Unit or moveDirection\r\n    end\r\n\r\n    local function applyVerticalMovement()\r\n        if UserInputService:GetFocusedTextBox() then\r\n            return Vector3.new(0, 0, 0)\r\n        end\r\n\r\n        local verticalMovement = Vector3.new(0, 0, 0)\r\n        if UserInputService:IsKeyDown(FLIGHT_SETTINGS.Controls.UP) then\r\n            verticalMovement = verticalMovement + Vector3.new(0, FLIGHT_SETTINGS.Speed, 0)\r\n        end\r\n        if UserInputService:IsKeyDown(FLIGHT_SETTINGS.Controls.DOWN) then\r\n            verticalMovement = verticalMovement + Vector3.new(0, -FLIGHT_SETTINGS.Speed, 0)\r\n        end\r\n        \r\n        return verticalMovement\r\n    end\r\n\r\n    -- Add this function to handle flight updates\r\n    local function updateFlight(deltaTime)\r\n        if not FLIGHT_SETTINGS.Enabled or not flightEnabled then return end\r\n        \r\n        local character = player.Character\r\n        if not character then return end\r\n        \r\n        local humanoid = character:FindFirstChild(\"Humanoid\")\r\n        local rootPart = character:FindFirstChild(\"HumanoidRootPart\")\r\n        if not humanoid or not rootPart then return end\r\n        \r\n        rootPart.Velocity = Vector3.new(0, 0, 0)  -- Cancel gravity\r\n        \r\n        updateMovementVectors()\r\n        \r\n        local finalMoveDirection = calculateMovementDirection()\r\n        if finalMoveDirection.Magnitude > 0 then\r\n            rootPart.CFrame = rootPart.CFrame + (finalMoveDirection * FLIGHT_SETTINGS.Speed * deltaTime)\r\n        end\r\n        \r\n        local verticalMovement = applyVerticalMovement() * deltaTime\r\n        rootPart.CFrame = rootPart.CFrame + verticalMovement\r\n    end\r\n\r\n    local function createDrawing(type, properties)\r\n        local element = Drawing.new(type)\r\n        for property, value in pairs(properties) do\r\n            element[property] = value\r\n        end\r\n        return element\r\n    end\r\n\r\n    local function createVeggForPlayer(otherPlayer)\r\n        if veggElements[otherPlayer] then return end\r\n        \r\n        veggElements[otherPlayer] = {\r\n            box = createDrawing(\"Square\", {\r\n                Thickness = VEGG_SETTINGS.BoxThickness,\r\n                Color = VEGG_SETTINGS.BoxColor,\r\n                Transparency = VEGG_SETTINGS.BoxTransparency,\r\n                Filled = false,\r\n                Visible = false,\r\n                ZIndex = 2\r\n            }),\r\n            boxOutline = createDrawing(\"Square\", {\r\n                Thickness = 2,\r\n                Color = Color3.new(0, 0, 0),\r\n                Transparency = 1,\r\n                Filled = false,\r\n                Visible = false,\r\n                ZIndex = 1\r\n            }),\r\n            healthBarBackground = createDrawing(\"Square\", {  -- Renamed for clarity\r\n                Thickness = 1,\r\n                Color = Color3.fromRGB(0, 0, 0),\r\n                Transparency = 0.5,  -- Made semi-transparent\r\n                Filled = true,\r\n                Visible = false,\r\n                ZIndex = 1\r\n            }),\r\n            healthBar = createDrawing(\"Square\", {\r\n                Thickness = 1,\r\n                Color = Color3.fromRGB(0, 255, 0),\r\n                Filled = true,\r\n                Visible = false,\r\n                ZIndex = 2\r\n            }),\r\n            nameTag = createDrawing(\"Text\", {\r\n                Size = VEGG_SETTINGS.TextSize,\r\n                Center = true,\r\n                Outline = true,\r\n                Color = VEGG_SETTINGS.BoxColor,\r\n                Visible = false,\r\n                ZIndex = 3,\r\n                Font = Drawing.Fonts.System\r\n            }),\r\n            distance = createDrawing(\"Text\", {\r\n                Size = VEGG_SETTINGS.TextSize,\r\n                Center = true,\r\n                Outline = true,\r\n                Color = VEGG_SETTINGS.BoxColor,\r\n                Visible = false,\r\n                ZIndex = 3,\r\n                Font = Drawing.Fonts.System\r\n            }),\r\n            -- Basic skeleton (used for R6)\r\n            skeletonHead = createDrawing(\"Line\", {\r\n                Thickness = 1,\r\n                Color = VEGG_SETTINGS.SkeletonColor,\r\n                Transparency = 1,\r\n                Visible = false,\r\n                ZIndex = 2\r\n            }),\r\n            skeletonTorso = createDrawing(\"Line\", {\r\n                Thickness = 1,\r\n                Color = VEGG_SETTINGS.SkeletonColor,\r\n                Transparency = 1,\r\n                Visible = false,\r\n                ZIndex = 2\r\n            }),\r\n            skeletonLeftArm = createDrawing(\"Line\", {\r\n                Thickness = 1,\r\n                Color = VEGG_SETTINGS.SkeletonColor,\r\n                Transparency = 1,\r\n                Visible = false,\r\n                ZIndex = 2\r\n            }),\r\n            skeletonRightArm = createDrawing(\"Line\", {\r\n                Thickness = 1,\r\n                Color = VEGG_SETTINGS.SkeletonColor,\r\n                Transparency = 1,\r\n                Visible = false,\r\n                ZIndex = 2\r\n            }),\r\n            skeletonLeftLeg = createDrawing(\"Line\", {\r\n                Thickness = 1,\r\n                Color = VEGG_SETTINGS.SkeletonColor,\r\n                Transparency = 1,\r\n                Visible = false,\r\n                ZIndex = 2\r\n            }),\r\n            skeletonRightLeg = createDrawing(\"Line\", {\r\n                Thickness = 1,\r\n                Color = VEGG_SETTINGS.SkeletonColor,\r\n                Transparency = 1,\r\n                Visible = false,\r\n                ZIndex = 2\r\n            }),\r\n            \r\n            -- Additional R15 skeleton parts\r\n            skeletonLeftForearm = createDrawing(\"Line\", {\r\n                Thickness = 1,\r\n                Color = VEGG_SETTINGS.SkeletonColor,\r\n                Transparency = 1,\r\n                Visible = false,\r\n                ZIndex = 2\r\n            }),\r\n            skeletonRightForearm = createDrawing(\"Line\", {\r\n                Thickness = 1,\r\n                Color = VEGG_SETTINGS.SkeletonColor,\r\n                Transparency = 1,\r\n                Visible = false,\r\n                ZIndex = 2\r\n            }),\r\n            skeletonLeftLowerLeg = createDrawing(\"Line\", {\r\n                Thickness = 1,\r\n                Color = VEGG_SETTINGS.SkeletonColor,\r\n                Transparency = 1,\r\n                Visible = false,\r\n                ZIndex = 2\r\n            }),\r\n            skeletonRightLowerLeg = createDrawing(\"Line\", {\r\n                Thickness = 1,\r\n                Color = VEGG_SETTINGS.SkeletonColor,\r\n                Transparency = 1,\r\n                Visible = false,\r\n                ZIndex = 2\r\n            })\r\n        }\r\n    end\r\n\r\n    local function removeVeggForPlayer(otherPlayer)\r\n        if veggElements[otherPlayer] then\r\n            for _, element in pairs(veggElements[otherPlayer]) do\r\n                element:Remove()\r\n            end\r\n            veggElements[otherPlayer] = nil\r\n        end\r\n    end\r\n\r\n    local function updateFovCircle()\r\n        local camera = getCamera()\r\n        if not camera then return end\r\n        \r\n        if VEGG_SETTINGS.FovCircle.Enabled then\r\n            fovCircle.Visible = true\r\n            -- Use screen center instead of mouse position\r\n            local screenCenter = Vector2.new(camera.ViewportSize.X/2, camera.ViewportSize.Y/2)\r\n            fovCircle.Position = screenCenter\r\n            fovCircle.Radius = VEGG_SETTINGS.FovCircle.Radius\r\n        else\r\n            fovCircle.Visible = false\r\n        end\r\n    end\r\n\r\n    local function getPredictedPosition(targetPart)\r\n        if not targetPart then return nil end\r\n        \r\n        local targetPosition = targetPart.Position\r\n        \r\n        if SIKTE_SETTINGS.PartOffsets[targetPart.Name] then\r\n            targetPosition = targetPosition + SIKTE_SETTINGS.PartOffsets[targetPart.Name]\r\n        end\r\n        \r\n        if SIKTE_SETTINGS.UsePrediction and targetPart:IsA(\"BasePart\") then\r\n            local predictionFactor = AUTO_PREDICTION_SETTINGS.Enabled and getAutoPrediction() or SIKTE_SETTINGS.PredictionFactor\r\n            targetPosition = targetPosition + (targetPart.Velocity * predictionFactor)\r\n        end\r\n        \r\n        return targetPosition\r\n    end\r\n    local function getClosestTarget()\r\n        if not SIKTE_SETTINGS.TargetMode then return nil end\r\n        \r\n        local closestCharacter = nil\r\n        local cameraPosition = camera.CFrame.Position\r\n        local screenCenter = Vector2.new(camera.ViewportSize.X/2, camera.ViewportSize.Y/2)\r\n        \r\n        if SIKTE_SETTINGS.TargetMode == \"Crosshair\" then\r\n            local closestAngle = math.rad(VEGG_SETTINGS.FovCircle.Radius * 0.15)\r\n            \r\n            for _, otherPlayer in ipairs(Players:GetPlayers()) do\r\n                if otherPlayer ~= player and \r\n                otherPlayer.Character and \r\n                otherPlayer.Character:FindFirstChild(SIKTE_SETTINGS.TargetPart) then\r\n                    \r\n                    if SIKTE_SETTINGS.TeamCheck and isOnSameTeam(player, otherPlayer) then\r\n                        continue\r\n                    end\r\n                    \r\n                    if SIKTE_SETTINGS.HealthCheck then\r\n                        local humanoid = otherPlayer.Character:FindFirstChild(\"Humanoid\")\r\n                        if humanoid and humanoid.Health <= 0 then\r\n                            continue\r\n                        end\r\n                    end\r\n                    \r\n                    local targetPart = otherPlayer.Character[SIKTE_SETTINGS.TargetPart]\r\n                    local targetPosition = getPredictedPosition(targetPart)\r\n                    if not targetPosition then continue end\r\n                    \r\n                    local distance = (targetPosition - cameraPosition).Magnitude\r\n                    \r\n                    if distance >= SIKTE_SETTINGS.MinDistance and distance <= SIKTE_SETTINGS.MaxDistance then\r\n                        local screenPoint, onScreen = camera:WorldToViewportPoint(targetPosition)\r\n                        \r\n                        if onScreen then\r\n                            local screenPosition = Vector2.new(screenPoint.X, screenPoint.Y)\r\n                            local pixelDistance = (screenPosition - screenCenter).Magnitude\r\n                            \r\n                            if pixelDistance <= VEGG_SETTINGS.FovCircle.Radius then\r\n                                local angle = math.atan2(pixelDistance, camera.ViewportSize.Y)\r\n                                \r\n                                if angle < closestAngle then\r\n                                    if SIKTE_SETTINGS.UseWallCheck then\r\n                                        local toTarget = (targetPart.Position - cameraPosition).Unit\r\n                                        local rayParams = RaycastParams.new()\r\n                                        rayParams.FilterDescendantsInstances = {player.Character, otherPlayer.Character}\r\n                                        rayParams.FilterType = Enum.RaycastFilterType.Blacklist\r\n                                        \r\n                                        local rayResult = workspace:Raycast(cameraPosition, toTarget * distance, rayParams)\r\n                                        \r\n                                        if not rayResult then\r\n                                            closestAngle = angle\r\n                                            closestCharacter = otherPlayer.Character\r\n                                        end\r\n                                    else\r\n                                        closestAngle = angle\r\n                                        closestCharacter = otherPlayer.Character\r\n                                    end\r\n                                end\r\n                            end\r\n                        end\r\n                    end\r\n                end\r\n            end\r\n        else -- Distance mode\r\n            local closestDistance = math.huge\r\n            local playerPosition = player.Character and player.Character:FindFirstChild(\"HumanoidRootPart\") and \r\n                                player.Character.HumanoidRootPart.Position\r\n            \r\n            if not playerPosition then return nil end\r\n            \r\n            for _, otherPlayer in ipairs(Players:GetPlayers()) do\r\n                if otherPlayer ~= player and \r\n                otherPlayer.Character and \r\n                otherPlayer.Character:FindFirstChild(SIKTE_SETTINGS.TargetPart) then\r\n                    \r\n                    if SIKTE_SETTINGS.TeamCheck and isOnSameTeam(player, otherPlayer) then\r\n                        continue\r\n                    end\r\n                    \r\n                    if SIKTE_SETTINGS.HealthCheck then\r\n                        local humanoid = otherPlayer.Character:FindFirstChild(\"Humanoid\")\r\n                        if humanoid and humanoid.Health <= 0 then\r\n                            continue\r\n                        end\r\n                    end\r\n                    \r\n                    local targetPart = otherPlayer.Character[SIKTE_SETTINGS.TargetPart]\r\n                    local targetPosition = getPredictedPosition(targetPart)\r\n                    if not targetPosition then continue end\r\n                    \r\n                    local distance = (targetPosition - playerPosition).Magnitude\r\n                    \r\n                    if distance >= SIKTE_SETTINGS.MinDistance and distance <= SIKTE_SETTINGS.MaxDistance then\r\n                        if distance < closestDistance then\r\n                            if SIKTE_SETTINGS.UseWallCheck then\r\n                                local toTarget = (targetPart.Position - cameraPosition).Unit\r\n                                local rayParams = RaycastParams.new()\r\n                                rayParams.FilterDescendantsInstances = {player.Character, otherPlayer.Character}\r\n                                rayParams.FilterType = Enum.RaycastFilterType.Blacklist\r\n                                \r\n                                local rayResult = workspace:Raycast(cameraPosition, toTarget * distance, rayParams)\r\n                                \r\n                                if not rayResult then\r\n                                    closestDistance = distance\r\n                                    closestCharacter = otherPlayer.Character\r\n                                end\r\n                            else\r\n                                closestDistance = distance\r\n                                closestCharacter = otherPlayer.Character\r\n                            end\r\n                        end\r\n                    end\r\n                end\r\n            end\r\n        end\r\n        \r\n        return closestCharacter\r\n    end\r\n\r\n    local function isCrosshairOnTarget()\r\n        -- Get mouse position for ray origin\r\n        local mouseLocation = UserInputService:GetMouseLocation()\r\n        local unitRay = camera:ViewportPointToRay(mouseLocation.X, mouseLocation.Y)\r\n        \r\n        local raycastParams = RaycastParams.new()\r\n        raycastParams.FilterType = Enum.RaycastFilterType.Blacklist\r\n        raycastParams.FilterDescendantsInstances = {player.Character}\r\n        \r\n        local raycastResult = workspace:Raycast(unitRay.Origin, unitRay.Direction * 1000, raycastParams)\r\n        \r\n        if raycastResult then\r\n            for _, otherPlayer in pairs(Players:GetPlayers()) do\r\n                if otherPlayer ~= player and \r\n                otherPlayer.Character and \r\n                raycastResult.Instance:IsDescendantOf(otherPlayer.Character) then\r\n                    \r\n                    if TRIGGERBOT_SETTINGS.TeamCheck and isOnSameTeam(player, otherPlayer) then\r\n                        return false\r\n                    end\r\n                    \r\n                    if TRIGGERBOT_SETTINGS.HealthCheck then\r\n                        local humanoid = otherPlayer.Character:FindFirstChild(\"Humanoid\")\r\n                        if humanoid and humanoid.Health <= 0 then\r\n                            return false\r\n                        end\r\n                    end\r\n                    \r\n                    local targetPart = otherPlayer.Character:FindFirstChild(SIKTE_SETTINGS.TargetPart)\r\n                    \r\n                    if targetPart then\r\n                        local hitPart = raycastResult.Instance\r\n                        local distance = (hitPart.Position - targetPart.Position).Magnitude\r\n                        \r\n                        if distance <= 2 then\r\n                            return true\r\n                        end\r\n                    end\r\n                end\r\n            end\r\n        end\r\n        \r\n        return false\r\n    end\r\n\r\n    local function isTargetVisible(target)\r\n        if not target or not target:FindFirstChild(SIKTE_SETTINGS.TargetPart) then return false end\r\n        \r\n        local targetPart = target[SIKTE_SETTINGS.TargetPart]\r\n        local cameraPosition = camera.CFrame.Position\r\n        \r\n        -- Calculate direction and distance to target\r\n        local toTarget = (targetPart.Position - cameraPosition)\r\n        local distance = toTarget.Magnitude\r\n        \r\n        -- Setup ray parameters\r\n        local rayParams = RaycastParams.new()\r\n        rayParams.FilterDescendantsInstances = {player.Character, target} -- Fixed typo in FilterDescendantsInstances\r\n        rayParams.FilterType = Enum.RaycastFilterType.Blacklist\r\n        \r\n        -- Cast ray from camera to target\r\n        local rayResult = workspace:Raycast(cameraPosition, toTarget.Unit * distance, rayParams)\r\n        \r\n        -- Target is visible if ray doesn\'t hit anything\r\n        return rayResult == nil\r\n    end\r\n\r\n    local function simulateMouseClick()\r\n        mouse1press()\r\n        task.wait(0.05)\r\n        mouse1release()\r\n    end\r\n\r\n    local function checkAutoClick()\r\n        if not TRIGGERBOT_SETTINGS.Enabled or not TRIGGERBOT_SETTINGS.Active then return end\r\n        \r\n        local shouldClick = false\r\n        \r\n        if TRIGGERBOT_SETTINGS.Mode == \"With Aimbot\" then\r\n            -- For \"With Aimbot\" mode, use both aimbot\'s target and triggerbot\'s health check\r\n            if SIKTE_SETTINGS.AimbotEnabled and currentTarget then\r\n                if TRIGGERBOT_SETTINGS.HealthCheck then\r\n                    local humanoid = currentTarget:FindFirstChild(\"Humanoid\")\r\n                    if humanoid and humanoid.Health <= 0 then\r\n                        return\r\n                    end\r\n                end\r\n                shouldClick = true\r\n            end\r\n        elseif TRIGGERBOT_SETTINGS.Mode == \"Crosshair\" then\r\n            -- For \"Crosshair\" mode, health check is handled in isCrosshairOnTarget\r\n            shouldClick = isCrosshairOnTarget()\r\n        end\r\n        \r\n        if shouldClick then\r\n            local currentTime = tick()\r\n            if currentTime - lastClickTime >= TRIGGERBOT_SETTINGS.ClickDelay then\r\n                task.spawn(function()\r\n                    simulateMouseClick()\r\n                end)\r\n                lastClickTime = currentTime\r\n            end\r\n        end\r\n    end\r\n\r\n    local function performMouseAim(targetPosition)\r\n        -- Get screen positions\r\n        local targetScreenPos = camera:WorldToViewportPoint(targetPosition)\r\n        local mousePos = UserInputService:GetMouseLocation()\r\n        \r\n        -- Calculate base deltas\r\n        local deltaX = (targetScreenPos.X - mousePos.X)\r\n        local deltaY = (targetScreenPos.Y - mousePos.Y)\r\n        \r\n        -- Calculate distance for scaling\r\n        local distance = math.sqrt(deltaX * deltaX + deltaY * deltaY)\r\n        \r\n        -- Skip tiny movements\r\n        if distance < 1 then return end\r\n        \r\n        -- Scale larger movements\r\n        local scaleFactor = distance > 100 and 100 / distance or 1\r\n        \r\n        -- Apply smoothing if enabled\r\n        if SIKTE_SETTINGS.UseSmoothing then\r\n            deltaX = deltaX * SIKTE_SETTINGS.SmoothSpeed\r\n            deltaY = deltaY * SIKTE_SETTINGS.SmoothSpeed\r\n        end\r\n        \r\n        -- Apply scaled sensitivity\r\n        local sens = math.min(SIKTE_SETTINGS.MouseSensitivity, 1) * 0.5 * scaleFactor\r\n        deltaX = deltaX * sens\r\n        deltaY = deltaY * sens\r\n        \r\n        -- Add exponential dampening\r\n        if math.abs(deltaX) > 10 then deltaX = deltaX * (10 / math.abs(deltaX)) end\r\n        if math.abs(deltaY) > 10 then deltaY = deltaY * (10 / math.abs(deltaY)) end\r\n        \r\n        -- Final bounds check\r\n        deltaX = math.clamp(deltaX, -10, 10)\r\n        deltaY = math.clamp(deltaY, -10, 10)\r\n        \r\n        -- Move mouse\r\n        mousemoverel(deltaX, deltaY)\r\n    end\r\n\r\n    local function updateSikte(deltaTime)\r\n        local camera = getCamera()\r\n        if not camera then return end\r\n        if not SIKTE_SETTINGS.AimbotEnabled or not sikteEnabled then \r\n            return \r\n        end\r\n        \r\n        if currentTarget then\r\n            if not currentTarget or\r\n            not currentTarget:FindFirstChild(SIKTE_SETTINGS.TargetPart) or\r\n            not currentTarget:FindFirstChild(\"Humanoid\") or\r\n            currentTarget.Humanoid.Health <= 0 then\r\n                currentTarget = nil\r\n                return\r\n            end\r\n\r\n            local targetPart = currentTarget[SIKTE_SETTINGS.TargetPart]\r\n            if not targetPart then return end\r\n\r\n            -- Get predicted position\r\n            local targetPosition = getPredictedPosition(targetPart)\r\n            if not targetPosition then return end\r\n\r\n            -- Check if predicted position is on screen and within FOV\r\n            local screenPoint, onScreen = camera:WorldToViewportPoint(targetPosition)\r\n            if not onScreen then \r\n                currentTarget = nil\r\n                return \r\n            end\r\n\r\n            local screenCenter = Vector2.new(camera.ViewportSize.X/2, camera.ViewportSize.Y/2)\r\n            local screenPosition = Vector2.new(screenPoint.X, screenPoint.Y)\r\n            local pixelDistance = (screenPosition - screenCenter).Magnitude\r\n            \r\n            if pixelDistance > VEGG_SETTINGS.FovCircle.Radius then\r\n                currentTarget = nil\r\n                return\r\n            end\r\n\r\n            if SIKTE_SETTINGS.UseWallCheck and not isTargetVisible(currentTarget) then\r\n                currentTarget = nil\r\n                return\r\n            end\r\n\r\n            if SIKTE_SETTINGS.AimMethod == \"Camera\" then\r\n                if SIKTE_SETTINGS.UseSmoothing then\r\n                    camera.CFrame = camera.CFrame:Lerp(\r\n                        CFrame.new(camera.CFrame.Position, targetPosition),\r\n                        SIKTE_SETTINGS.SmoothSpeed\r\n                    )\r\n                else\r\n                    camera.CFrame = CFrame.new(camera.CFrame.Position, targetPosition)\r\n                end\r\n            else -- \"MouseMove\"\r\n                performMouseAim(targetPosition)\r\n            end\r\n        else\r\n            currentTarget = getClosestTarget()\r\n        end\r\n        \r\n        checkAutoClick()\r\n    end\r\n\r\n    local function updateVeggForPlayer(otherPlayer)\r\n        local camera = getCamera()\r\n        if not camera then return end\r\n        if not VEGG_SETTINGS.Enabled then\r\n            if veggElements[otherPlayer] then\r\n                for _, element in pairs(veggElements[otherPlayer]) do\r\n                    element.Visible = false\r\n                end\r\n            end\r\n            return\r\n        end\r\n\r\n        if VEGG_SETTINGS.TeamCheck and isOnSameTeam(player, otherPlayer) then\r\n            if veggElements[otherPlayer] then\r\n                for _, element in pairs(veggElements[otherPlayer]) do\r\n                    element.Visible = false\r\n                end\r\n            end\r\n            return\r\n        end\r\n\r\n        local character = otherPlayer.Character\r\n        local localCharacter = player.Character\r\n\r\n        if not character or not character:FindFirstChild(\"HumanoidRootPart\") or not localCharacter or not localCharacter:FindFirstChild(\"HumanoidRootPart\") then\r\n            if veggElements[otherPlayer] then\r\n                for _, element in pairs(veggElements[otherPlayer]) do\r\n                    element.Visible = false\r\n                end\r\n            end\r\n            return\r\n        end\r\n\r\n        local humanoid = character:FindFirstChild(\"Humanoid\")\r\n        local rootPart = character:FindFirstChild(\"HumanoidRootPart\")\r\n        local localRootPart = localCharacter:FindFirstChild(\"HumanoidRootPart\")\r\n        \r\n        if not rootPart or (VEGG_SETTINGS.HealthCheck and humanoid and humanoid.Health <= 0) then\r\n            if veggElements[otherPlayer] then\r\n                for _, element in pairs(veggElements[otherPlayer]) do\r\n                    element.Visible = false\r\n                end\r\n            end\r\n            return\r\n        end\r\n\r\n        -- Calculate box size using fixed height method\r\n        local fixedHeight = 3.5 -- Reduced from 5 to 3.5 for better fit\r\n        local rootPosition = rootPart.Position\r\n        local topPosition = rootPosition + Vector3.new(0, fixedHeight, 0)\r\n        local bottomPosition = rootPosition - Vector3.new(0, fixedHeight/2, 0)\r\n        \r\n        local _, rootOnScreen = camera:WorldToViewportPoint(rootPosition)\r\n        if not rootOnScreen then\r\n            if veggElements[otherPlayer] then\r\n                for _, element in pairs(veggElements[otherPlayer]) do\r\n                    element.Visible = false\r\n                end\r\n            end\r\n            return\r\n        end\r\n        \r\n        local topPoint = camera:WorldToViewportPoint(topPosition)\r\n        local bottomPoint = camera:WorldToViewportPoint(bottomPosition)\r\n        \r\n        local boxHeight = math.abs(topPoint.Y - bottomPoint.Y)\r\n        local boxWidth = boxHeight * 0.6 -- Maintain aspect ratio\r\n        \r\n        local screenPosition = camera:WorldToViewportPoint(rootPart.Position)\r\n        \r\n        local elements = veggElements[otherPlayer]\r\n        if not elements then return end\r\n        \r\n        -- Calculate box position with the new height\r\n        local boxPosition = Vector2.new(\r\n            screenPosition.X - (boxWidth / 2),\r\n            screenPosition.Y - (boxHeight / 2) + (boxHeight * 0.1) -- Small offset to center better\r\n        )\r\n\r\n        -- Calculate distance from local player to target\r\n        local distanceInStuds = (localRootPart.Position - rootPart.Position).Magnitude\r\n        local distanceInMeters = math.floor(distanceInStuds * 0.28)\r\n        \r\n        if VEGG_SETTINGS.BoxEnabled then\r\n            elements.boxOutline.Size = Vector2.new(boxWidth, boxHeight)\r\n            elements.boxOutline.Position = boxPosition\r\n            elements.boxOutline.Visible = true\r\n\r\n            elements.box.Size = Vector2.new(boxWidth, boxHeight)\r\n            elements.box.Position = boxPosition\r\n            elements.box.Color = currentTarget == character and VEGG_SETTINGS.TargetColor or VEGG_SETTINGS.BoxColor\r\n            elements.box.Visible = true\r\n        else\r\n            elements.box.Visible = false\r\n            elements.boxOutline.Visible = false\r\n        end\r\n        \r\n        if VEGG_SETTINGS.HealthEnabled and humanoid then\r\n            local healthPercent = humanoid.Health / humanoid.MaxHealth\r\n            local barWidth = 2\r\n            local padding = 4\r\n            \r\n            local healthBarX = boxPosition.X - barWidth - padding - 2\r\n            \r\n            elements.healthBarBackground.Size = Vector2.new(barWidth + 2, boxHeight + 2)\r\n            elements.healthBarBackground.Position = Vector2.new(healthBarX - 1, boxPosition.Y - 1)\r\n            elements.healthBarBackground.Visible = true\r\n            \r\n            local healthBarHeight = boxHeight * healthPercent\r\n            elements.healthBar.Size = Vector2.new(barWidth, healthBarHeight)\r\n            elements.healthBar.Position = Vector2.new(healthBarX, boxPosition.Y + boxHeight - healthBarHeight)\r\n            \r\n            local fullHealth = Color3.fromRGB(0, 180, 0)\r\n            local noHealth = Color3.fromRGB(180, 0, 0)\r\n            elements.healthBar.Color = noHealth:Lerp(fullHealth, healthPercent)\r\n            elements.healthBar.Visible = true\r\n        else\r\n            elements.healthBarBackground.Visible = false\r\n            elements.healthBar.Visible = false\r\n        end\r\n        \r\n        if VEGG_SETTINGS.NameEnabled then\r\n            elements.nameTag.Text = otherPlayer.DisplayName\r\n            elements.nameTag.Position = Vector2.new(boxPosition.X + boxWidth/2, boxPosition.Y - 20)\r\n            elements.nameTag.Color = currentTarget == character and VEGG_SETTINGS.TargetColor or VEGG_SETTINGS.BoxColor\r\n            elements.nameTag.Visible = true\r\n        else\r\n            elements.nameTag.Visible = false\r\n        end\r\n        \r\n        if VEGG_SETTINGS.DistanceEnabled then\r\n            local distanceOffset = 2\r\n            elements.distance.Text = distanceInMeters .. \" m\"\r\n            elements.distance.Position = Vector2.new(boxPosition.X + boxWidth/2, boxPosition.Y + boxHeight + distanceOffset)\r\n            elements.distance.Color = currentTarget == character and VEGG_SETTINGS.TargetColor or VEGG_SETTINGS.BoxColor\r\n            elements.distance.Visible = true\r\n        else\r\n            elements.distance.Visible = false\r\n        end\r\n\r\n        if VEGG_SETTINGS.SkeletonEnabled then\r\n            local function drawBone(line, part1, part2)\r\n                local p1 = character:FindFirstChild(part1)\r\n                local p2 = character:FindFirstChild(part2)\r\n                \r\n                if p1 and p2 then\r\n                    local pos1, vis1 = camera:WorldToViewportPoint(p1.Position)\r\n                    local pos2, vis2 = camera:WorldToViewportPoint(p2.Position)\r\n                    \r\n                    if vis1 and vis2 and pos1.Z > 0 and pos2.Z > 0 then\r\n                        line.From = Vector2.new(pos1.X, pos1.Y)\r\n                        line.To = Vector2.new(pos2.X, pos2.Y)\r\n                        -- Only change color to yellow if targeted, otherwise stay white\r\n                        line.Color = currentTarget == character and VEGG_SETTINGS.TargetColor or VEGG_SETTINGS.SkeletonColor\r\n                        line.Visible = true\r\n                    else\r\n                        line.Visible = false\r\n                    end\r\n                else\r\n                    line.Visible = false\r\n                end\r\n            end\r\n\r\n            -- Check if R6 or R15\r\n            local isR6 = character:FindFirstChild(\"Torso\") ~= nil\r\n            \r\n            if isR6 then\r\n                -- R6 connections (simple)\r\n                drawBone(elements.skeletonHead, \"Head\", \"Torso\")\r\n                drawBone(elements.skeletonLeftArm, \"Torso\", \"Left Arm\")\r\n                drawBone(elements.skeletonRightArm, \"Torso\", \"Right Arm\")\r\n                drawBone(elements.skeletonLeftLeg, \"Torso\", \"Left Leg\")\r\n                drawBone(elements.skeletonRightLeg, \"Torso\", \"Right Leg\")\r\n                \r\n                -- Hide R15-specific parts\r\n                elements.skeletonTorso.Visible = false\r\n                elements.skeletonLeftForearm.Visible = false\r\n                elements.skeletonRightForearm.Visible = false\r\n                elements.skeletonLeftLowerLeg.Visible = false\r\n                elements.skeletonRightLowerLeg.Visible = false\r\n            else\r\n                -- R15 connections (detailed)\r\n                drawBone(elements.skeletonHead, \"Head\", \"UpperTorso\")\r\n                drawBone(elements.skeletonTorso, \"UpperTorso\", \"LowerTorso\")\r\n                \r\n                -- Left Arm\r\n                drawBone(elements.skeletonLeftArm, \"UpperTorso\", \"LeftUpperArm\")\r\n                drawBone(elements.skeletonLeftForearm, \"LeftUpperArm\", \"LeftLowerArm\")\r\n                \r\n                -- Right Arm\r\n                drawBone(elements.skeletonRightArm, \"UpperTorso\", \"RightUpperArm\")\r\n                drawBone(elements.skeletonRightForearm, \"RightUpperArm\", \"RightLowerArm\")\r\n                \r\n                -- Left Leg\r\n                drawBone(elements.skeletonLeftLeg, \"LowerTorso\", \"LeftUpperLeg\")\r\n                drawBone(elements.skeletonLeftLowerLeg, \"LeftUpperLeg\", \"LeftLowerLeg\")\r\n                \r\n                -- Right Leg\r\n                drawBone(elements.skeletonRightLeg, \"LowerTorso\", \"RightUpperLeg\")\r\n                drawBone(elements.skeletonRightLowerLeg, \"RightUpperLeg\", \"RightLowerLeg\")\r\n            end\r\n        else\r\n            -- Hide all skeleton lines when disabled\r\n            if elements then\r\n                elements.skeletonHead.Visible = false\r\n                elements.skeletonTorso.Visible = false\r\n                elements.skeletonLeftArm.Visible = false\r\n                elements.skeletonRightArm.Visible = false\r\n                elements.skeletonLeftLeg.Visible = false\r\n                elements.skeletonRightLeg.Visible = false\r\n                elements.skeletonLeftForearm.Visible = false\r\n                elements.skeletonRightForearm.Visible = false\r\n                elements.skeletonLeftLowerLeg.Visible = false\r\n                elements.skeletonRightLowerLeg.Visible = false\r\n            end\r\n        end\r\n    end\r\n\r\n    pcall(function()\r\n        for _, con in pairs(getconnections(workspace.CurrentCamera.Changed)) do\r\n            task.wait()\r\n            con:Disable()\r\n        end\r\n    end)\r\n\r\n    pcall(function()\r\n        for _, con in pairs(getconnections(workspace.CurrentCamera:GetPropertyChangedSignal(\"CFrame\"))) do\r\n            task.wait()\r\n            con:Disable()\r\n        end\r\n    end)\r\n\r\n    if getgc then\r\n        for _, key in pairs(getgc(true)) do \r\n            local function updateKey(instanceType)\r\n                if pcall(function() return rawget(key, instanceType) end) \r\n                    and typeof(rawget(key, instanceType)) == \'table\' \r\n                    and (rawget(key, instanceType))[1] == \'kick\' then\r\n                        key.tvk = {\r\n                            \'kick\',\r\n                            function() \r\n                                return game.Workspace:WaitForChild(\'\')\r\n                            end\r\n                        }\r\n                end\r\n            end\r\n\r\n            pcall(function()\r\n                updateKey(\'indexInstance\')\r\n                updateKey(\'namecallInstance\')\r\n            end)\r\n        end\r\n    end\r\n\r\n    local function startSystem()\r\n        for _, otherPlayer in ipairs(Players:GetPlayers()) do\r\n            if otherPlayer ~= player then\r\n                createVeggForPlayer(otherPlayer)\r\n            end\r\n        end\r\n        \r\n        RunService:BindToRenderStep(\r\n            \"SikteUpdate\",\r\n            Enum.RenderPriority.Camera.Value,\r\n            updateSikte\r\n        )\r\n        \r\n        RunService.RenderStepped:Connect(function(deltaTime)\r\n            if TRIGGERBOT_SETTINGS.Enabled then\r\n                checkAutoClick()\r\n            end\r\n            updateFovCircle()\r\n            updateSpin(deltaTime)\r\n            updateHitboxes()\r\n            for _, otherPlayer in ipairs(Players:GetPlayers()) do\r\n                if otherPlayer ~= player then\r\n                    updateVeggForPlayer(otherPlayer)\r\n                end\r\n            end\r\n        end)\r\n        RunService.Heartbeat:Connect(function(deltaTime)\r\n            updateFlight(deltaTime)\r\n            updateSpeed(deltaTime)\r\n            if ANTILOCK_SETTINGS.Enabled then\r\n                updateAntilock(deltaTime)\r\n            end\r\n        end)\r\n        RunService.Heartbeat:Connect(handleVerticalMovement)\r\n        RunService.Stepped:Connect(updateNoclip)\r\n    end\r\n\r\n    Players.PlayerAdded:Connect(function(otherPlayer)\r\n        if otherPlayer ~= player then\r\n            createVeggForPlayer(otherPlayer)\r\n        end\r\n    end)\r\n\r\n    Players.PlayerRemoving:Connect(function(otherPlayer)\r\n        removeVeggForPlayer(otherPlayer)\r\n    end)\r\n\r\n    player.CharacterAdded:Connect(function()\r\n        sikteEnabled = false\r\n        currentTarget = nil\r\n    end)\r\n\r\n    player.CharacterRemoving:Connect(function()\r\n        if ANTILOCK_SETTINGS.Enabled then\r\n            removeVisualCharacter()\r\n        end\r\n    end)\r\n\r\n    player.CharacterAdded:Connect(function(character)\r\n        if ANTILOCK_SETTINGS.Enabled then\r\n            task.wait(0.5) -- Wait for character to load\r\n            createVisualCharacter()\r\n        end\r\n    end)\r\n\r\n    local library = loadstring(game:HttpGet(\"https://raw.githubusercontent.com/MoistMonkey420/NapoleonHook/refs/heads/main/uilib/Pepsi.lua\"))()\r\n    local Wait = library.subs.Wait\r\n\r\n    local NapoleonHook = library:CreateWindow({\r\n        Name = \"Napoleon Hook\",\r\n        Themeable = {\r\n            Info = \"By CyberKevin2019\"\r\n        }\r\n    })\r\n\r\n    -- Aimbot Tab\r\n    local AimbotTab = NapoleonHook:CreateTab({\r\n        Name = \"Aimbot\"\r\n    })\r\n\r\n    local AimbotMainSection = AimbotTab:CreateSection({\r\n        Name = \"Aimbot\"\r\n    })\r\n\r\n    AimbotMainSection:AddToggle({\r\n        Name = \"Enable\",\r\n        Flag = \"AimbotSection_Enabled\",\r\n        Keybind = {\r\n            Mode = \"Hold\",\r\n            Value = Enum.UserInputType.MouseButton2\r\n        },\r\n        Callback = function(Value)\r\n            SIKTE_SETTINGS.AimbotEnabled = Value\r\n            if Value then\r\n                sikteEnabled = true\r\n            else\r\n                sikteEnabled = false\r\n                currentTarget = nil\r\n            end\r\n        end\r\n    })\r\n    AimbotMainSection:AddDropdown({\r\n        Name = \"Target Mode\",\r\n        Flag = \"AimbotSection_TargetMode\",\r\n        Value = \"Crosshair\",\r\n        List = {\"Crosshair\", \"Distance\"},\r\n        Callback = function(Value)\r\n            SIKTE_SETTINGS.TargetMode = Value\r\n        end\r\n    })\r\n\r\n    AimbotMainSection:AddToggle({\r\n        Name = \"Wall Check\",\r\n        Flag = \"AimbotSection_WallCheck\",\r\n        Callback = function(Value)\r\n            SIKTE_SETTINGS.UseWallCheck = Value\r\n        end\r\n    })\r\n\r\n    AimbotMainSection:AddToggle({\r\n        Name = \"Health Check\",\r\n        Flag = \"AimbotSection_HealthCheck\",\r\n        Callback = function(Value)\r\n            SIKTE_SETTINGS.HealthCheck = Value\r\n        end\r\n    })\r\n\r\n    AimbotMainSection:AddDropdown({\r\n        Name = \"Aim Method\",\r\n        Flag = \"AimbotSection_AimMethod\",\r\n        Value = \"Camera\",\r\n        List = {\"Camera\", \"MouseMove\"},\r\n        Callback = function(Value)\r\n            SIKTE_SETTINGS.AimMethod = Value\r\n        end\r\n    })\r\n\r\n    AimbotMainSection:AddDropdown({\r\n        Name = \"Target Part\",\r\n        Flag = \"AimbotSection_TargetPart\",\r\n        Value = \"Head\",\r\n        List = {\"Head\", \"HumanoidRootPart\", \"UpperTorso\", \"LowerTorso\", \"Torso\"},\r\n        Callback = function(Value)\r\n            SIKTE_SETTINGS.TargetPart = Value\r\n        end\r\n    })\r\n\r\n    AimbotMainSection:AddSlider({\r\n        Name = \"Mouse Sensitivity\",\r\n        Flag = \"AimbotSection_MouseSensitivity\",\r\n        Value = 0.5,\r\n        Min = 0.01,\r\n        Max = 0.5,\r\n        Precise = 2,\r\n        Callback = function(Value)\r\n            SIKTE_SETTINGS.MouseSensitivity = Value\r\n        end\r\n    })\r\n\r\n    local TriggerbotSection = AimbotTab:CreateSection({\r\n        Name = \"Triggerbot\",\r\n        Side = \"Right\"\r\n    })\r\n\r\n    TriggerbotSection:AddToggle({\r\n        Name = \"Enable Triggerbot\",\r\n        Flag = \"TriggerbotSection_Enabled\",\r\n        Keybind = {\r\n            Mode = \"Hold\",\r\n            Value = Enum.UserInputType.MouseButton2\r\n        },\r\n        Callback = function(Value)\r\n            TRIGGERBOT_SETTINGS.Enabled = Value\r\n            TRIGGERBOT_SETTINGS.Active = Value\r\n        end\r\n    })\r\n\r\n    TriggerbotSection:AddDropdown({\r\n        Name = \"Trigger Mode\",\r\n        Flag = \"TriggerbotSection_Mode\",\r\n        Value = \"With Aimbot\",\r\n        List = {\"With Aimbot\", \"Crosshair\"},\r\n        Callback = function(Value)\r\n            TRIGGERBOT_SETTINGS.Mode = Value\r\n        end\r\n    })\r\n\r\n    TriggerbotSection:AddSlider({\r\n        Name = \"Click Delay\",\r\n        Flag = \"TriggerbotSection_ClickDelay\",\r\n        Value = 0.1,\r\n        Min = 0.01,\r\n        Max = 1.00,\r\n        Precise = 2,\r\n        Format = function(Value)\r\n            return \"Click Delay: \" .. tostring(Value) .. \"s\"\r\n        end,\r\n        Callback = function(Value)\r\n            TRIGGERBOT_SETTINGS.ClickDelay = Value\r\n        end\r\n    })\r\n\r\n    local SmoothingSection = AimbotTab:CreateSection({\r\n        Name = \"Smoothing\",\r\n        Side = \"Right\"\r\n    })\r\n\r\n    SmoothingSection:AddToggle({\r\n        Name = \"Enable Smoothing\",\r\n        Flag = \"SmoothingSection_Enabled\",\r\n        Callback = function(Value)\r\n            SIKTE_SETTINGS.UseSmoothing = Value\r\n        end\r\n    })\r\n\r\n    SmoothingSection:AddSlider({\r\n        Name = \"Smooth Speed\",\r\n        Flag = \"SmoothingSection_Speed\",\r\n        Value = 0.8,\r\n        Min = 0.01,\r\n        Max = 1.00,\r\n        Precise = 2,\r\n        Callback = function(Value)\r\n            SIKTE_SETTINGS.SmoothSpeed = Value\r\n        end\r\n    })\r\n\r\n    local PredictionSection = AimbotTab:CreateSection({\r\n        Name = \"Prediction\",\r\n        Side = \"Right\"\r\n    })\r\n\r\n    PredictionSection:AddToggle({\r\n        Name = \"Enable Prediction\",\r\n        Flag = \"PredictionSection_Enabled\",\r\n        Callback = function(Value)\r\n            SIKTE_SETTINGS.UsePrediction = Value\r\n        end\r\n    })\r\n\r\n    PredictionSection:AddToggle({\r\n        Name = \"Auto Prediction\",\r\n        Flag = \"PredictionSection_Auto\",\r\n        Callback = function(Value)\r\n            AUTO_PREDICTION_SETTINGS.Enabled = Value\r\n        end\r\n    })\r\n\r\n    PredictionSection:AddSlider({\r\n        Name = \"Prediction Amount\",\r\n        Flag = \"PredictionSection_Amount\",\r\n        Value = 0.138,\r\n        Min = 0.01,\r\n        Max = 1.00,\r\n        Precise = 3,\r\n        Callback = function(Value)\r\n            SIKTE_SETTINGS.PredictionFactor = Value\r\n        end\r\n    })\r\n\r\n    -- Visual Tab\r\n    local VisualTab = NapoleonHook:CreateTab({\r\n        Name = \"Visual\"\r\n    })\r\n\r\n    local ESPSection = VisualTab:CreateSection({\r\n        Name = \"ESP\"\r\n    })\r\n\r\n    ESPSection:AddToggle({\r\n        Name = \"Box ESP\",\r\n        Flag = \"ESPSection_Box\",\r\n        Callback = function(Value)\r\n            VEGG_SETTINGS.BoxEnabled = Value\r\n        end\r\n    })\r\n\r\n    ESPSection:AddToggle({\r\n        Name = \"Skeleton ESP\",\r\n        Flag = \"ESPSection_Skeleton\",\r\n        Callback = function(Value)\r\n            VEGG_SETTINGS.SkeletonEnabled = Value\r\n        end\r\n    })\r\n\r\n    ESPSection:AddToggle({\r\n        Name = \"Health Bar\",\r\n        Flag = \"ESPSection_HealthBar\",\r\n        Callback = function(Value)\r\n            VEGG_SETTINGS.HealthEnabled = Value\r\n        end\r\n    })\r\n\r\n    ESPSection:AddToggle({\r\n        Name = \"Name ESP\",\r\n        Flag = \"ESPSection_Name\",\r\n        Callback = function(Value)\r\n            VEGG_SETTINGS.NameEnabled = Value\r\n        end\r\n    })\r\n\r\n    ESPSection:AddToggle({\r\n        Name = \"Distance ESP\",\r\n        Flag = \"ESPSection_Distance\",\r\n        Callback = function(Value)\r\n            VEGG_SETTINGS.DistanceEnabled = Value\r\n        end\r\n    })\r\n\r\n    ESPSection:AddToggle({\r\n        Name = \"Health Check\",\r\n        Flag = \"ESPSection_HealthCheck\",\r\n        Callback = function(Value)\r\n            VEGG_SETTINGS.HealthCheck = Value\r\n        end\r\n    })\r\n\r\n    local FOVSection = VisualTab:CreateSection({\r\n        Name = \"FOV Circle\",\r\n        Side = \"Right\"\r\n    })\r\n\r\n    FOVSection:AddToggle({\r\n        Name = \"Show FOV\",\r\n        Flag = \"FOVSection_Show\",\r\n        Callback = function(Value)\r\n            VEGG_SETTINGS.FovCircle.Enabled = Value\r\n        end\r\n    })\r\n\r\n    FOVSection:AddSlider({\r\n        Name = \"FOV Size\",\r\n        Flag = \"FOVSection_Size\",\r\n        Value = 100,\r\n        Min = 0,\r\n        Max = 1000,\r\n        Callback = function(Value)\r\n            VEGG_SETTINGS.FovCircle.Radius = Value\r\n        end\r\n    })\r\n\r\n    -- Movement Tab\r\n    local MovementTab = NapoleonHook:CreateTab({\r\n        Name = \"Movement\"\r\n    })\r\n\r\n    local FlightSection = MovementTab:CreateSection({\r\n        Name = \"Flight\"\r\n    })\r\n\r\n    FlightSection:AddToggle({\r\n        Name = \"Enable Flight\",\r\n        Flag = \"FlightSection_Enable\",\r\n        Keybind = {\r\n            Mode = \"Toggle\",\r\n            Value = Enum.KeyCode.V\r\n        },\r\n        Callback = function(Value)\r\n            FLIGHT_SETTINGS.Enabled = Value\r\n            flightEnabled = Value\r\n        end\r\n    })\r\n\r\n    FlightSection:AddSlider({\r\n        Name = \"Flight Speed\",\r\n        Flag = \"FlightSection_Speed\",\r\n        Value = 50,\r\n        Min = 1,\r\n        Max = 1000,\r\n        Format = function(Value)\r\n            return \"Flight Speed: \" .. tostring(Value) .. \" studs\"\r\n        end,\r\n        Callback = function(Value)\r\n            FLIGHT_SETTINGS.Speed = Value\r\n        end\r\n    })\r\n\r\n    local SpeedSection = MovementTab:CreateSection({\r\n        Name = \"Speed\",\r\n        Side = \"Right\"\r\n    })\r\n\r\n    SpeedSection:AddToggle({\r\n        Name = \"Enable Speed\",\r\n        Flag = \"SpeedSection_Enable\",\r\n        Keybind = {\r\n            Mode = \"Toggle\",\r\n            Value = Enum.KeyCode.X\r\n        },\r\n        Callback = function(Value)\r\n            SPEED_SETTINGS.Enabled = Value\r\n            speedEnabled = Value\r\n        end\r\n    })\r\n\r\n    SpeedSection:AddSlider({\r\n        Name = \"Speed Amount\",\r\n        Flag = \"SpeedSection_Amount\",\r\n        Value = 50,\r\n        Min = 1,\r\n        Max = 1000,\r\n        Format = function(Value)\r\n            return \"Speed: \" .. tostring(Value) .. \" studs\"\r\n        end,\r\n        Callback = function(Value)\r\n            SPEED_SETTINGS.Speed = Value\r\n        end\r\n    })\r\n\r\n    -- Misc Tab\r\n    local MiscTab = NapoleonHook:CreateTab({\r\n        Name = \"Misc\"\r\n    })\r\n\r\n    local SpinSection = MiscTab:CreateSection({\r\n        Name = \"Spin\"\r\n    })\r\n\r\n    SpinSection:AddToggle({\r\n        Name = \"Enable Spin\",\r\n        Flag = \"SpinSection_Enable\",\r\n        Callback = function(Value)\r\n            spinEnabled = Value\r\n        end\r\n    })\r\n\r\n    SpinSection:AddSlider({\r\n        Name = \"Spin Speed\",\r\n        Flag = \"SpinSection_Speed\",\r\n        Value = 50,\r\n        Min = 1,\r\n        Max = 50,\r\n        Callback = function(Value)\r\n            spinSpeed = Value\r\n        end\r\n    })\r\n\r\n    local NoclipSection = MiscTab:CreateSection({\r\n        Name = \"Noclip\"\r\n    })\r\n\r\n    NoclipSection:AddToggle({\r\n        Name = \"Enable Noclip\",\r\n        Flag = \"NoclipSection_Enable\",\r\n        Callback = function(Value)\r\n            NOCLIP_SETTINGS.Enabled = Value\r\n            \r\n            if Value then\r\n                NOCLIP_SETTINGS.Noclipping = RunService.Stepped:Connect(function()\r\n                    if player.Character then\r\n                        for _, child in pairs(player.Character:GetDescendants()) do\r\n                            if child:IsA(\"BasePart\") and child.CanCollide then\r\n                                child.CanCollide = false\r\n                            end\r\n                        end\r\n                    end\r\n                end)\r\n            else\r\n                if NOCLIP_SETTINGS.Noclipping then\r\n                    NOCLIP_SETTINGS.Noclipping:Disconnect()\r\n                    NOCLIP_SETTINGS.Noclipping = nil\r\n                end\r\n            end\r\n        end\r\n    })\r\n\r\n    local TeamCheckSection = MiscTab:CreateSection({\r\n        Name = \"Team Check\"\r\n    })\r\n\r\n    TeamCheckSection:AddToggle({\r\n        Name = \"Enable Team Check\",\r\n        Flag = \"TeamCheckSection_Enable\",\r\n        Callback = function(Value)\r\n            VEGG_SETTINGS.TeamCheck = Value\r\n            SIKTE_SETTINGS.TeamCheck = Value\r\n            TRIGGERBOT_SETTINGS.TeamCheck = Value\r\n        end\r\n    })\r\n\r\n    local SpeechSection = MiscTab:CreateSection({\r\n        Name = \"Napoleon Speech\",\r\n        Side = \"Right\"\r\n    })\r\n\r\n    SpeechSection:AddToggle({\r\n        Name = \"Enable Speech\",\r\n        Flag = \"SpeechSection_Enable\",\r\n        Callback = function(Value)\r\n            SPEECH_SETTINGS.Enabled = Value\r\n            if Value then\r\n                startSpeech()\r\n            end\r\n        end\r\n    })\r\n\r\n    SpeechSection:AddSlider({\r\n        Name = \"Sentence Delay\",\r\n        Flag = \"SpeechSection_SentenceDelay\",\r\n        Value = 3,\r\n        Min = 1,\r\n        Max = 10,\r\n        Format = function(Value)\r\n            return \"Sentence Delay: \" .. tostring(Value) .. \"s\"\r\n        end,\r\n        Callback = function(Value)\r\n            SPEECH_SETTINGS.Delay = Value\r\n        end\r\n    })\r\n\r\n    SpeechSection:AddSlider({\r\n        Name = \"Loop Delay\",\r\n        Flag = \"SpeechSection_LoopDelay\",\r\n        Value = 5,\r\n        Min = 1,\r\n        Max = 20,\r\n        Format = function(Value)\r\n            return \"Loop Delay: \" .. tostring(Value) .. \"s\"\r\n        end,\r\n        Callback = function(Value)\r\n            SPEECH_SETTINGS.LoopDelay = Value\r\n        end\r\n    })\r\n\r\n    local AntilockSection = MiscTab:CreateSection({\r\n        Name = \"Antilock\",\r\n        Side = \"Right\"\r\n    })\r\n\r\n    AntilockSection:AddToggle({\r\n        Name = \"Enable Antilock\",\r\n        Flag = \"AntilockSection_Enable\",\r\n        Keybind = {\r\n            Mode = \"Toggle\",\r\n            Value = Enum.KeyCode.Z\r\n        },\r\n        Callback = function(Value)\r\n            ANTILOCK_SETTINGS.Enabled = Value\r\n            if Value then\r\n                createVisualCharacter()\r\n                task.wait(0.1)\r\n                if ANTILOCK_SETTINGS.VisualHumanoid then\r\n                    workspace.CurrentCamera.CameraSubject = ANTILOCK_SETTINGS.VisualHumanoid\r\n                end\r\n            else\r\n                removeVisualCharacter()\r\n            end\r\n        end\r\n    })\r\n\r\n    AntilockSection:AddSlider({\r\n        Name = \"Radius\",\r\n        Flag = \"AntilockSection_Radius\",\r\n        Value = 15,\r\n        Min = 5,\r\n        Max = 50,\r\n        Format = function(Value)\r\n            return \"Radius: \" .. tostring(Value) .. \" studs\"\r\n        end,\r\n        Callback = function(Value)\r\n            ANTILOCK_SETTINGS.Radius = Value\r\n        end\r\n    })\r\n\r\n    local HitboxSection = MiscTab:CreateSection({\r\n        Name = \"Hitbox Expander\",\r\n        Side = \"Right\"\r\n    })\r\n\r\n    HitboxSection:AddToggle({\r\n        Name = \"Enable Hitboxes\",\r\n        Flag = \"HitboxSection_Enable\",\r\n        Callback = function(Value)\r\n            HITBOX_SETTINGS.Enabled = Value\r\n        end\r\n    })\r\n\r\n    HitboxSection:AddSlider({\r\n        Name = \"Hitbox Size\",\r\n        Flag = \"HitboxSection_Size\",\r\n        Value = 20,\r\n        Min = 1,\r\n        Max = 50,\r\n        Format = function(Value)\r\n            return \"Size: \" .. tostring(Value)\r\n        end,\r\n        Callback = function(Value)\r\n            HITBOX_SETTINGS.Size = Value\r\n        end\r\n    })\r\n\r\n    HitboxSection:AddSlider({\r\n        Name = \"Transparency\",\r\n        Flag = \"HitboxSection_Transparency\",\r\n        Value = 0.7,\r\n        Min = 0,\r\n        Max = 1,\r\n        Precise = 2,\r\n        Format = function(Value)\r\n            return \"Transparency: \" .. tostring(Value)\r\n        end,\r\n        Callback = function(Value)\r\n            HITBOX_SETTINGS.Transparency = Value\r\n        end\r\n    })\r\n\r\n    -- Load the UI\r\n    library:Notify({\r\n        Title = \"Napoleon Hook\",\r\n        Message = \"Loaded successfully!\",\r\n        Time = 3\r\n    })\r\n\r\n    -- Create keybind indicator GUI\r\n    local ScreenGui = Instance.new(\"ScreenGui\")\r\n    local Frame = Instance.new(\"Frame\")\r\n    local TitleLabel = Instance.new(\"TextLabel\")\r\n    local StatusContainer = Instance.new(\"Frame\")\r\n    local UIListLayout = Instance.new(\"UIListLayout\")\r\n\r\n    -- GUI Properties\r\n    ScreenGui.Name = \"KeybindIndicator\"\r\n    ScreenGui.Parent = game:GetService(\"CoreGui\")\r\n\r\n    Frame.Name = \"MainFrame\"\r\n    Frame.Parent = ScreenGui\r\n    Frame.BackgroundColor3 = Color3.fromRGB(45, 45, 45)\r\n    Frame.BorderSizePixel = 0\r\n    Frame.Position = UDim2.new(0, 20, 0, 20)\r\n    Frame.Size = UDim2.new(0, 200, 0, 180) -- Reduced height since we removed 2 features\r\n    Frame.Active = true\r\n    Frame.Draggable = true\r\n\r\n    TitleLabel.Parent = Frame\r\n    TitleLabel.BackgroundTransparency = 1\r\n    TitleLabel.Position = UDim2.new(0.1, 0, 0.05, 0)\r\n    TitleLabel.Size = UDim2.new(0.8, 0, 0.1, 0)\r\n    TitleLabel.Font = Enum.Font.SourceSansBold\r\n    TitleLabel.Text = \"Keybinds\"\r\n    TitleLabel.TextColor3 = Color3.fromRGB(255, 255, 255)\r\n    TitleLabel.TextSize = 18\r\n\r\n    StatusContainer.Name = \"StatusContainer\"\r\n    StatusContainer.Parent = Frame\r\n    StatusContainer.BackgroundTransparency = 1\r\n    StatusContainer.Position = UDim2.new(0.1, 0, 0.2, 0)\r\n    StatusContainer.Size = UDim2.new(0.8, 0, 0.75, 0)\r\n\r\n    UIListLayout.Parent = StatusContainer\r\n    UIListLayout.SortOrder = Enum.SortOrder.LayoutOrder\r\n    UIListLayout.Padding = UDim.new(0, 5)\r\n\r\n    -- Function to create status labels\r\n    local function createStatusLabel(name)\r\n        local label = Instance.new(\"TextLabel\")\r\n        label.BackgroundTransparency = 1\r\n        label.Size = UDim2.new(1, 0, 0, 20)\r\n        label.Font = Enum.Font.SourceSans\r\n        label.TextSize = 14\r\n        label.TextXAlignment = Enum.TextXAlignment.Left\r\n        label.TextColor3 = Color3.fromRGB(255, 255, 255)\r\n        label.Parent = StatusContainer\r\n        \r\n        -- Create an inner label for the status text (ON/OFF)\r\n        local statusText = Instance.new(\"TextLabel\")\r\n        statusText.BackgroundTransparency = 1\r\n        statusText.Position = UDim2.new(0.6, 0, 0, 0)\r\n        statusText.Size = UDim2.new(0.4, 0, 1, 0)\r\n        statusText.Font = Enum.Font.SourceSansBold\r\n        statusText.TextSize = 14\r\n        statusText.TextXAlignment = Enum.TextXAlignment.Right\r\n        statusText.Parent = label\r\n        \r\n        return {\r\n            main = label,\r\n            status = statusText\r\n        }\r\n    end\r\n\r\n    -- Create status labels for each feature\r\n    local features = {\r\n        Aimbot = createStatusLabel(\"Aimbot\"),\r\n        Triggerbot = createStatusLabel(\"Triggerbot\"),\r\n        Antilock = createStatusLabel(\"Antilock\"),\r\n        Flight = createStatusLabel(\"Flight\"),\r\n        Speed = createStatusLabel(\"Speed\")\r\n    }\r\n\r\n    -- Update feature statuses\r\n    game:GetService(\"RunService\").RenderStepped:Connect(function()\r\n        for name, labels in pairs(features) do\r\n            labels.main.Text = name .. \":\"\r\n            \r\n            local isEnabled = false\r\n            if name == \"Aimbot\" then\r\n                isEnabled = SIKTE_SETTINGS.AimbotEnabled and sikteEnabled\r\n            elseif name == \"Triggerbot\" then\r\n                isEnabled = TRIGGERBOT_SETTINGS.Enabled and TRIGGERBOT_SETTINGS.Active\r\n            elseif name == \"Antilock\" then\r\n                isEnabled = ANTILOCK_SETTINGS.Enabled\r\n            elseif name == \"Flight\" then\r\n                isEnabled = FLIGHT_SETTINGS.Enabled and flightEnabled\r\n            elseif name == \"Speed\" then\r\n                isEnabled = SPEED_SETTINGS.Enabled and speedEnabled\r\n            end\r\n            \r\n            labels.status.Text = isEnabled and \"ON\" or \"OFF\"\r\n            labels.status.TextColor3 = isEnabled and Color3.fromRGB(0, 255, 0) or Color3.fromRGB(255, 0, 0)\r\n        end\r\n    end)\r\n\r\n    startSystem()\r\n"
